def f(g):
    bg=g[0][0]; H,W=len(g),len(g[0])
    comps=[]; seen=set()
    for i in range(H):
        for j in range(W):
            if (i,j) not in seen and g[i][j]!=bg:
                col=g[i][j]; st=[(i,j)]; cells={(i,j)}
                while st:
                    y,x=st.pop()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and (ny,nx) not in cells:
                            cells.add((ny,nx)); st.append((ny,nx))
                seen|=cells; comps.append((col,cells))
    out=[r[:] for r in g]
    for col,cells in comps:
        if len(cells)<2: continue
        r0=min(y for y,_ in cells); r1=max(y for y,_ in cells)
        c0=min(x for _,x in cells); c1=max(x for _,x in cells)
        for y in range(r0,r1+1):
            for x in range(c0,c1+1):
                out[y][x]=col
    return out
